    // Pemisah selain spasi: getline dengan argumen KETIGA
    string csv = "Andi,20,Bandung";
    istringstream baca(csv);
    string potongan;
    while (getline(baca, potongan, ',')) {
        cout << "[" << potongan << "]";
    }
    cout << endl;                      // [Andi][20][Bandung]

